def compute(vars):
    lease = vars["v1"]
    loan = vars["v2"]
    service_contracts = vars["v3"]
    total = lease + loan + service_contracts

    return {
        "value": total,
        "trace": {
            "lease_receivables": lease,
            "loan_receivables": loan,
            "financed_service_contracts": service_contracts,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
